using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestHelpers
    {
        public static SchoolContext CreateContext(string dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            return new SchoolContext(options);
        }

        public static SchoolContext CreateContextWithData(string dbName = null)
        {
            var context = CreateContext(dbName);
            SeedData(context);
            return context;
        }

        public static void SeedData(SchoolContext context)
        {
            var department = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 100000m,
                StartDate = new DateTime(2020, 1, 1)
            };
            context.Departments.Add(department);

            var student1 = new Student
            {
                ID = 1,
                LastName = "Smith",
                FirstMidName = "John",
                EnrollmentDate = new DateTime(2023, 9, 1),
                Enrollments = new List<Enrollment>()
            };
            var student2 = new Student
            {
                ID = 2,
                LastName = "Adams",
                FirstMidName = "Jane",
                EnrollmentDate = new DateTime(2023, 8, 15),
                Enrollments = new List<Enrollment>()
            };
            var student3 = new Student
            {
                ID = 3,
                LastName = "Baker",
                FirstMidName = "Bob",
                EnrollmentDate = new DateTime(2022, 1, 10),
                Enrollments = new List<Enrollment>()
            };
            context.Students.AddRange(student1, student2, student3);

            var instructor1 = new Instructor
            {
                ID = 10,
                LastName = "Kapoor",
                FirstMidName = "Anand",
                HireDate = new DateTime(2015, 3, 11),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment { InstructorID = 10, Location = "Room 101" }
            };
            context.Instructors.Add(instructor1);

            var course1 = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            };
            var course2 = new Course
            {
                CourseID = 4022,
                Title = "Microeconomics",
