using System;
using System.Linq;
using Xunit;
using ContosoUniversity.Services;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain any leftover notifications from other tests (static queue)
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_FourParams_EnqueuesNotification()
        {
            _service.SendNotification("Student", "1", EntityOperation.CREATE, "TestUser");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("TestUser", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.Contains("Student (ID: 1)", notification.Message);
            Assert.Contains("has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_FiveParams_WithDisplayName_EnqueuesNotification()
        {
            _service.SendNotification("Course", "101", "Chemistry", EntityOperation.UPDATE, "Admin");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("101", notification.EntityId);
            Assert.Equal("UPDATE", notification.Operation);
            Assert.Equal("Admin", notification.CreatedBy);
            Assert.Contains("Course 'Chemistry'", notification.Message);
            Assert.Contains("has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_GeneratesCorrectMessage()
        {
            _service.SendNotification("Department", "5", "Engineering", EntityOperation.DELETE, "System");

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("DELETE", notification.Operation);
            Assert.Contains("Department 'Engineering'", notification.Message);
            Assert.Contains("has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_NullUserName_DefaultsToSystem()
        {
            _service.SendNotification("Student", "2", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_NullDisplayName_UsesIdInMessage()
        {
            _service.SendNotification("Student", "42", null, EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("Student (ID: 42)", notification.Message);
        }

        [Fact]
        public void SendNotification_EmptyDisplayName_UsesIdInMessage()
        {
            _service.SendNotification("Student", "42", "  ", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.Contains("Student (ID: 42)", notification.Message);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var notification = _service.ReceiveNotification();

            Assert.Null(notification);
        }

        [Fact]
        public void ReceiveNotification_DequeuedInOrder()
        {
            _service.SendNotification("A", "1", EntityOperation.CREATE);
            _service.SendNotification("B", "2", EntityOperation.UPDATE);
            _service.SendNotification("C", "3", EntityOperation.DELETE);

            var n1 = _service.ReceiveNotification();
            var n2 = _service.ReceiveNotification();
            var n3 = _service.ReceiveNotification();

            Assert.Equal("A", n1.EntityType);
            Assert.Equal("B", n2.EntityType);
            Assert.Equal("C", n3.EntityType);
            Assert.Null(_service.ReceiveNotification());
        }

        [Fact]
        public void SendNotification_QueueCapEnforced_OldestDropped()
        {
            // Enqueue 502 items — the cap is 500
            for (int i = 0; i < 502; i++)
            {
                _service.SendNotification("Item", i.ToString(), EntityOperation.CREATE);
            }

            // Queue should be capped at 500 or fewer
            int count = 0;
            while (_service.ReceiveNotification() != null) count++;
            Assert.True(count <= 500, $"Queue should be capped at 500 but had {count} items");
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToApproximatelyNow()
        {
            var before = DateTime.Now;
            _service.SendNotification("Test", "1", EntityOperation.CREATE);
            var after = DateTime.Now;

            var notification = _service.ReceiveNotification();

            Assert.NotNull(notification);
            Assert.InRange(notification.CreatedAt, before.AddSeconds(-1), after.AddSeconds(1));
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op in this implementation, just verify no exception
            var ex = Record.Exception(() => _service.MarkAsRead(999));
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_CreateOperation_MessageContainsCreated()
        {
            _service.SendNotification("Instructor", "5", "Dr. Jones", EntityOperation.CREATE);

            var notification = _service.ReceiveNotification();

            Assert.Equal("New Instructor 'Dr. Jones' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateOperation_MessageContainsUpdated()
        {
            _service.SendNotification("Course", "10", "Math 101", EntityOperation.UPDATE);

            var notification = _service.ReceiveNotification();

            Assert.Equal("Course 'Math 101' has been updated", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_MessageContainsDeleted()
        {
            _service.SendNotification("Department", "3", "Physics", EntityOperation.DELETE);

            var notification = _service.ReceiveNotification();

            Assert.Equal("Department 'Physics' has been deleted", notification.Message);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var items = Enumerable.Range(1, 50).AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(1, result.First());
            Assert.Equal(10, result.Last());
            Assert.Equal(1, result.PageIndex);
            Assert.Equal(5, result.TotalPages);
        }

        [Fact]
        public void Create_SecondPage_ReturnsCorrectItems()
        {
            var items = Enumerable.Range(1, 50).AsQueryable();

            var result = PaginatedList<int>.Create(items, 2, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(11, result.First());
            Assert.Equal(20, result.Last());
            Assert.Equal(2, result.PageIndex);
        }

        [Fact]
        public void Create_LastPage_ReturnsRemainingItems()
        {
            var items = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(items, 3, 10);

            Assert.Equal(5, result.Count);
            Assert.Equal(21, result.First());
            Assert.Equal(25, result.Last());
            Assert.Equal(3, result.PageIndex);
            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void HasPreviousPage_FirstPage_ReturnsFalse()
        {
            var items = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.False(result.HasPreviousPage);
        }

        [Fact]
        public void HasPreviousPage_SecondPage_ReturnsTrue()
        {
            var items = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(items, 2, 10);

            Assert.True(result.HasPreviousPage);
        }

        [Fact]
        public void HasNextPage_FirstPageOfTwo_ReturnsTrue()
        {
            var items = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse()
        {
            var items = Enumerable.Range(1, 20).AsQueryable();

            var result = PaginatedList<int>.Create(items, 2, 10);

            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void TotalPages_ExactDivision_CalculatesCorrectly()
        {
            var items = Enumerable.Range(1, 30).AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(3, result.TotalPages);
        }

        [Fact]
        public void TotalPages_NotExactDivision_RoundsUp()
        {
            var items = Enumerable.Range(1, 31).AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(4, result.TotalPages);
        }

        [Fact]
        public void TotalPages_SingleItem_ReturnsOne()
        {
            var items = Enumerable.Range(1, 1).AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.Equal(1, result.TotalPages);
            Assert.Single(result);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var items = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(items, 1, 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }
    }
}

